<?php get_header(); if(have_posts()): while(have_posts()): the_post(); $birth=get_post_meta(get_the_ID(),'avam_birth',true);$death=get_post_meta(get_the_ID(),'avam_death',true);$will=get_post_meta(get_the_ID(),'avam_will',true);$letter=get_post_meta(get_the_ID(),'avam_letter',true);$prayer=get_post_meta(get_the_ID(),'avam_prayer',true);$memory=get_post_meta(get_the_ID(),'avam_memory',true);$image=get_the_post_thumbnail_url(get_the_ID(),'large'); ?>
<section class="avam-single-hero"><div class="avam-container avam-single-grid"><div><?php if($image): ?><div class="avam-single-photo"><img src="<?php echo esc_url($image); ?>" alt="<?php echo esc_attr(get_the_title()); ?>"></div><?php endif; ?></div><div><div class="avam-single-meta">صفحه یادبود</div><h1 class="avam-single-name"><?php the_title(); ?></h1><?php if($birth||$death): ?><div class="avam-single-meta"><?php echo esc_html($birth); ?><?php if($birth&&$death) echo ' — '; ?><?php echo esc_html($death); ?></div><?php endif; ?></div></div></section>
<div class="avam-single-body"><section><h2>روایت زندگی</h2><div class="avam-richtext"><?php echo esc_html(get_the_content()); ?></div></section><?php foreach([['وصیت',$will],['نامه',$letter],['خاطره',$memory],['دعا',$prayer]] as $item): if($item[1]): ?><section><h2><?php echo esc_html($item[0]); ?></h2><div class="avam-richtext"><?php echo esc_html($item[1]); ?></div></section><?php endif; endforeach; ?></div>
<?php endwhile; endif; get_footer(); ?>